    --numGibbsSamples '${adv.numGibbsSamples}'
#end if
#if int(str($adv.numBootstraps)) > 0:
    --numBootstraps '${adv.numBootstraps}'
#end if
--thinningFactor '${adv.thinningFactor}'
${adv.perTranscriptPrior}
--sigDigits '${adv.sigDigits}'
